@pytest.mark.intent
@pytest.mark.parametrize(
    "board",
    [
        "not_contiguous",
        "off_grid",
        "food_on_snake",
    ],
)
def test_reset_to_rejects_an_invalid_board(board):
    inp, _ = _load("TC-01")
    body = _cells(inp["body"])
    food = tuple(inp["food"])
    if board == "not_contiguous":
        body = [body[0], body[2]]
    elif board == "off_grid":
        body = [(r, c + 1) for r, c in body]
    else:
        food = body[1]
    env = Snake(view=inp["view"], size=inp["size"])
    env.reset(0)
    with pytest.raises(ValueError) as excinfo:
        env.reset_to(body, inp["heading"], food)
    assert not isinstance(excinfo.value, NotImplementedError)

